package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Value-dictionary GC must be deferred per retired ID, not all-or-nothing: a pinned SNAPSHOT reader only protects IDs
 * whose removal it predates. IDs retired before the oldest pinned snapshot must still be reclaimed while newer
 * retirements stay resolvable for the readers that need them.
 */
public class LmdbValueGcRetirementTest {

	@TempDir
	File dataDir;

	@Test
	public void pinnedReaderDoesNotBlockOlderRetirements() throws Exception {
		LmdbStore store = new LmdbStore(new File(dataDir, "store"), new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			ValueFactory vf = SimpleValueFactory.getInstance();
			IRI pred = vf.createIRI("http://example.com/p");
			IRI subjectV = vf.createIRI("http://example.com/v");
			IRI subjectW = vf.createIRI("http://example.com/w");

			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subjectV, pred, vf.createLiteral("v-value"));
				connection.addStatement(subjectW, pred, vf.createLiteral("w-value"));
				connection.addStatement(vf.createIRI("http://example.com/keeper"), pred, vf.createLiteral("keep"));
				connection.commit();
			}

			try (NotifyingSailConnection readerA = store.getConnection()) {
				readerA.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(readerA, subjectV, pred)).containsExactly("v-value");

				// remove v while reader A is pinned before the removal: v's IDs must be retired, not reclaimed
				removeAtNone(store, subjectV, pred);

				assertThat(readObjects(readerA, vf.createIRI("http://example.com/v"), pred))
						.as("pinned reader A predates v's removal and must still resolve it")
						.containsExactly("v-value");
				readerA.commit();
			}

			try (NotifyingSailConnection readerB = store.getConnection()) {
				readerB.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(readerB, subjectW, pred)).containsExactly("w-value");

				// remove w while reader B is pinned before the removal. This commit's GC pass runs with reader B as
				// the oldest pinned snapshot, which postdates v's retirement: v must be reclaimed now, w must not.
				removeAtNone(store, subjectW, pred);

				ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
				assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
						.as("v's subject IRI was retired before reader B's snapshot; reader B must not block it")
						.isEqualTo(LmdbValue.UNKNOWN_ID);
				assertThat(valueStore.getId(vf.createLiteral("v-value")))
						.as("v's literal was retired before reader B's snapshot; reader B must not block it")
						.isEqualTo(LmdbValue.UNKNOWN_ID);

				assertThat(valueStore.getId(vf.createIRI("http://example.com/w")))
						.as("w was retired after reader B's snapshot and must stay resolvable")
						.isNotEqualTo(LmdbValue.UNKNOWN_ID);
				assertThat(readObjects(readerB, vf.createIRI("http://example.com/w"), pred))
						.as("pinned reader B predates w's removal and must still resolve it")
						.containsExactly("w-value");
				readerB.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	/**
	 * The remove → re-add → remove race: a retirement record is superseded when its ID is re-added (keeping the same ID
	 * via the retained value→ID mapping) and removed again at a later revision. Draining past the first removal's
	 * revision must ignore the stale ordered-index entry instead of reclaiming an ID that a reader pinned between the
	 * re-add and the second removal still needs.
	 */
	@Test
	public void supersededRetirementDoesNotTearNewerReader() throws Exception {
		LmdbStore store = new LmdbStore(new File(dataDir, "store"), new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			ValueFactory vf = SimpleValueFactory.getInstance();
			IRI pred = vf.createIRI("http://example.com/p");
			IRI subjectV = vf.createIRI("http://example.com/v");

			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subjectV, pred, vf.createLiteral("v-value"));
				connection.addStatement(vf.createIRI("http://example.com/keeper"), pred, vf.createLiteral("keep"));
				connection.commit();
			}
			ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
			long originalId = valueStore.getId(subjectV);
			assertThat(originalId).isNotEqualTo(LmdbValue.UNKNOWN_ID);

			try (NotifyingSailConnection readerOld = store.getConnection()) {
				readerOld.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(readerOld, subjectV, pred)).containsExactly("v-value");

				// first removal: retired behind readerOld
				removeAtNone(store, subjectV, pred);

				// re-add: the retained value→ID mapping hands back the same ID — load-bearing for the race
				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.addStatement(vf.createIRI("http://example.com/v"), pred, vf.createLiteral("v-value"));
					writer.commit();
				}
				assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
						.as("a re-added value must reuse its retained ID")
						.isEqualTo(originalId);

				try (NotifyingSailConnection readerMid = store.getConnection()) {
					readerMid.begin(IsolationLevels.SNAPSHOT);
					assertThat(readObjects(readerMid, subjectV, pred)).containsExactly("v-value");

					// second removal: supersedes the first retirement record at a newer revision
					removeAtNone(store, subjectV, pred);

					readerOld.commit();
					readerOld.close();

					// this commit drains with readerMid as the oldest pin: the watermark passes the FIRST removal's
					// revision but not the second, so the stale ordered entry must be discarded without reclaiming
					try (NotifyingSailConnection writer = store.getConnection()) {
						writer.begin(IsolationLevels.NONE);
						writer.addStatement(vf.createIRI("http://example.com/unrelated1"), pred,
								vf.createLiteral("u1"));
						writer.commit();
					}

					assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
							.as("reader pinned between re-add and second removal must keep v resolvable")
							.isNotEqualTo(LmdbValue.UNKNOWN_ID);
					assertThat(readObjects(readerMid, vf.createIRI("http://example.com/v"), pred))
							.as("readerMid predates the second removal and must still resolve v")
							.containsExactly("v-value");
					readerMid.commit();
				}
			}

			// The store branch caches the last pinned dataset for reuse, so readerMid's pin stays active (and
			// correctly keeps blocking the second retirement) until a fresh SNAPSHOT borrower retires the stale
			// cache and re-pins at the current revision — which postdates the second removal.
			try (NotifyingSailConnection fresh = store.getConnection()) {
				fresh.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(fresh, vf.createIRI("http://example.com/v"), pred)).isEmpty();
				fresh.commit();
			}

			// now the superseding (second) retirement drains and v is reclaimed
			try (NotifyingSailConnection writer = store.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.addStatement(vf.createIRI("http://example.com/unrelated2"), pred, vf.createLiteral("u2"));
				writer.commit();
			}
			assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
					.as("once no pinned reader predates the second removal, the superseding retirement must reclaim v")
					.isEqualTo(LmdbValue.UNKNOWN_ID);
		} finally {
			store.shutDown();
		}
	}

	/**
	 * Disabling {@code rdf4j.lmdb.valueGc.deferForPinnedReaders} restores eager reclamation: no retirement records are
	 * written and a pinned reader loses resolution of values removed after its snapshot (the documented pre-pinning
	 * degraded behavior).
	 */
	@Test
	public void killSwitchRestoresEagerReclamation() throws Exception {
		System.setProperty("rdf4j.lmdb.valueGc.deferForPinnedReaders", "false");
		try {
			LmdbStore store = new LmdbStore(new File(dataDir, "store"), new LmdbStoreConfig("spoc,posc"));
			store.init();
			try {
				ValueFactory vf = SimpleValueFactory.getInstance();
				IRI pred = vf.createIRI("http://example.com/p");
				IRI subjectV = vf.createIRI("http://example.com/v");

				try (NotifyingSailConnection connection = store.getConnection()) {
					connection.begin();
					connection.addStatement(subjectV, pred, vf.createLiteral("v-value"));
					connection.addStatement(vf.createIRI("http://example.com/keeper"), pred, vf.createLiteral("keep"));
					connection.commit();
				}
				try (NotifyingSailConnection reader = store.getConnection()) {
					reader.begin(IsolationLevels.SNAPSHOT);
					assertThat(readObjects(reader, subjectV, pred)).containsExactly("v-value");

					removeAtNone(store, subjectV, pred);

					ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
					assertThat(valueStore.hasRetiredIds())
							.as("no retirement records may be written while the kill switch is off")
							.isFalse();
					assertThat(valueStore.getId(vf.createIRI("http://example.com/v")))
							.as("eager reclamation must drop the dictionary entry despite the pinned reader")
							.isEqualTo(LmdbValue.UNKNOWN_ID);
					reader.commit();
				}
			} finally {
				store.shutDown();
			}
		} finally {
			System.clearProperty("rdf4j.lmdb.valueGc.deferForPinnedReaders");
		}
	}

	private static void removeAtNone(LmdbStore store, IRI subject, IRI predicate) {
		try (NotifyingSailConnection writer = store.getConnection()) {
			writer.begin(IsolationLevels.NONE);
			writer.removeStatements(subject, predicate, null);
			writer.commit();
		}
	}

	private static List<String> readObjects(NotifyingSailConnection connection, IRI subject, IRI predicate) {
		try (CloseableIteration<? extends Statement> statements = connection.getStatements(subject, predicate, null,
				false)) {
			return statements.stream().map(st -> st.getObject().stringValue()).sorted().collect(Collectors.toList());
		}
	}
}
